#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Generate Stellar Mall AI Interview PDF - with Chinese font support"""

from fpdf import FPDF
import os

OUTPUT_PATH = r"D:\Desktop\stellar-mall\Stellar_Mall_AI_面试题.pdf"
FONT_PATH = r"C:\Windows\Fonts\msyh.ttc"

class InterviewPDF(FPDF):
    def __init__(self):
        super().__init__()
        self.set_auto_page_break(auto=True, margin=20)
        # Add Chinese font (Microsoft YaHei)
        self.add_font("YaHei", "", FONT_PATH, uni=True)
        self.add_font("YaHei", "B", FONT_PATH, uni=True)  # fpdf2 will handle bold via style
        # Use a smaller embedded Unicode font for answer text to save space
        self.add_font("YaHeiBody", "", FONT_PATH, uni=True)

    def header(self):
        if self.page_no() > 1:
            self.set_font("YaHei", "", 8)
            self.set_text_color(120, 120, 120)
            self.cell(0, 8, "Stellar Mall AI \u9762\u8bd5\u9898", align="L")
            self.cell(0, 8, f"\u7b2c {self.page_no()} \u9875", align="R", new_x="LMARGIN", new_y="NEXT")
            self.line(10, 14, 200, 14)
            self.ln(4)

    def footer(self):
        if self.page_no() > 1:
            self.set_y(-15)
            self.set_font("YaHei", "", 7)
            self.set_text_color(160, 160, 160)
            self.cell(0, 10, "Generated on 2026-07-27 | Stellar Mall Project", align="C")

    def cover_page(self):
        self.add_page()
        self.ln(50)
        self.set_font("YaHei", "B", 28)
        self.set_text_color(30, 60, 114)
        self.cell(0, 15, "Stellar Mall", align="C", new_x="LMARGIN", new_y="NEXT")
        self.ln(4)
        self.set_font("YaHei", "", 20)
        self.set_text_color(50, 100, 150)
        self.cell(0, 12, "AI \u7cfb\u7edf\u9762\u8bd5\u9898\u96c6", align="C", new_x="LMARGIN", new_y="NEXT")
        self.ln(10)
        self.set_draw_color(30, 60, 114)
        self.set_line_width(0.5)
        mid = 105
        self.line(mid - 50, self.get_y(), mid + 50, self.get_y())
        self.ln(15)
        self.set_font("YaHei", "", 11)
        self.set_text_color(80, 80, 80)
        lines = [
            "\u8986\u76d6 RAG + Agent \u4e24\u5927\u6a21\u5757",
            "\u56db\u5927\u5c42\u7ea7\uff1a\u57fa\u7840 / \u8fdb\u9636 / \u6df1\u6c34\u533a / \u5f00\u653e\u9898",
            "\u5171 19 \u9053\u9762\u8bd5\u9898 + \u8be6\u7ec6\u89e3\u6790",
        ]
        for line in lines:
            self.cell(0, 9, line, align="C", new_x="LMARGIN", new_y="NEXT")
        self.ln(20)
        self.set_font("YaHei", "", 9)
        self.set_text_color(140, 140, 140)
        self.cell(0, 8, "Stellar Mall Project - rag-backend", align="C", new_x="LMARGIN", new_y="NEXT")

    def section_title(self, num, title):
        self.set_font("YaHei", "B", 15)
        self.set_text_color(30, 60, 114)
        self.ln(6)
        self.cell(0, 10, f"\u7ae0\u8282 {num}  {title}", new_x="LMARGIN", new_y="NEXT")
        self.set_draw_color(30, 60, 114)
        self.set_line_width(0.4)
        self.line(10, self.get_y(), 200, self.get_y())
        self.ln(4)

    def question(self, q_num, level, text):
        self.set_font("YaHei", "B", 10)
        tag = f"[Q{q_num}] ({level})"
        self.set_text_color(30, 60, 114)
        self.set_x(12)
        self.cell(0, 7, tag, new_x="LMARGIN", new_y="NEXT")
        self.set_x(18)
        self.set_font("YaHei", "", 9.5)
        self.set_text_color(30, 30, 30)
        self.multi_cell(182, 6.5, text)
        self.ln(2)

    def answer(self, a_num, text):
        self.set_font("YaHei", "B", 9.5)
        self.set_text_color(200, 60, 60)
        self.set_x(12)
        self.cell(0, 7, f"\u25b6 A{a_num}", new_x="LMARGIN", new_y="NEXT")
        self.set_font("YaHei", "", 9)
        self.set_text_color(40, 40, 40)
        self.set_x(18)
        self.multi_cell(182, 5.5, text)
        self.ln(3)


